    const LBL = { new:'New', improved:'Improved', fixed:'Fixed' };
    function changelog(){
      inEl.innerHTML = `<div class="pv-h"><span class="dv-sec">Changelog</span><h1>What is new</h1><p>Every release of the library, newest first. Subscribe to get each one in your inbox.</p></div>
        <div class="chg">${LOG.map(r => `<article class="chg-r"><div class="chg-side"><span class="chg-v">${r.v}</span><span class="chg-d">${r.d}</span></div><div class="chg-body"><h2>${r.t}</h2><ul>${r.items.map(it => `<li><span class="chg-tag k-${it[0]}">${LBL[it[0]]}</span><span class="chg-tx">${it[1]}${it[2] ? `<span class="chg-links">${it[2].map(n => `<button class="chg-link" data-n="${n}">${n}</button>`).join('')}</span>` : ''}</span></li>`).join('')}</ul></div></article>`).join('')}</div>`;
    }
    // roadmap with upvotes, shared through Supabase when it is set up, otherwise saved in this browser
    const SUPA = { url:'https://udqdwspscjsrtftucueo.supabase.co', key:'sb_publishable_CPlq5d-AQVoUTSYKLK63CQ_mJJYzaLh' };
    const LIVE = !!(SUPA.url && SUPA.key);
    let votes = {}, extra = [], remote = null, loading = false;
    try { votes = JSON.parse(localStorage.getItem('dmui-votes') || '{}'); extra = JSON.parse(localStorage.getItem('dmui-ideas') || '[]'); } catch(e) {}
    let voter = null;
    try { voter = localStorage.getItem('dmui-voter'); if (!voter){ voter = crypto.randomUUID(); localStorage.setItem('dmui-voter', voter); } } catch(e) { voter = crypto.randomUUID(); }
    // new-style publishable keys go in the apikey header only, older anon keys also as a bearer token
    const rpc = async (fn, body) => {
      const headers = { apikey:SUPA.key, 'Content-Type':'application/json' };
      if (!SUPA.key.startsWith('sb_')) headers.Authorization = 'Bearer ' + SUPA.key;
      const r = await fetch(`${SUPA.url}/rest/v1/rpc/${fn}`, { method:'POST', headers, body:JSON.stringify(body) });
      if (!r.ok) throw new Error(r.status); return r.json();
    };
    const BASE = [
      ['react','React components','Every component as a typed React component for Next.js, React and Astro, with npx designme add <name> --react.','shipped','Code'],
      ['astro','Astro components','Every component as an Astro component, with npx designme add <name> --astro.','shipped','Code'],
      ['tailwind','Tailwind versions','Every component styled with Tailwind classes instead of its own CSS.','progress','Code'],
      ['figma','Figma library','All components with variants, tokens and both styles as variable modes, free for subscribers.','progress','Design'],
      ['webflow','Webflow export','Paste components straight into Webflow with classes intact.','planned','Code'],
      ['framer','Framer export','Each component as a Framer code component with controls.','planned','Code'],
      ['kanban','Kanban board','Drag cards across columns with an agent that updates them.','shipped','Workspace'],
      ['upload','File upload','Drop zone with previews, progress and retry.','planned','Forms'],
      ['bulk','Table bulk actions','Select rows and act on them from a floating bar.','planned','Data'],
      ['editor','Rich text editor','A minimal editor with an inline AI menu.','shipped','Conversation'],
      ['empty','Empty states','A set of empty, error and first-run states.','planned','Product'],
      ['video','Video call tile','Participant tiles with live captions and speaking state.','planned','Collaboration']
    ];
    let sort = 'top', prefill = '';
    const items = () => remote ? remote : BASE.map(b => ({ id:b[0], t:b[1], d:b[2], s:b[3], tag:b[4] })).concat(extra);
    const count = it => (it.base || 0) + (votes[it.id] ? 1 : 0);
    const save = () => { if (LIVE) return; try { localStorage.setItem('dmui-votes', JSON.stringify(votes)); localStorage.setItem('dmui-ideas', JSON.stringify(extra)); } catch(e) {} };
    async function load(){
      if (!LIVE || loading) return; loading = true;
      try {
        const rows = await rpc('roadmap', { p_voter:voter });
        votes = {}; remote = rows.map(r => { if (r.voted) votes[r.id] = true; return { id:r.id, t:r.title, d:r.description, s:r.status, tag:r.tag, base:Number(r.votes) - (r.voted ? 1 : 0), at:r.created_at }; });
        if ($('#rm-list') && pv.classList.contains('open')) $('#rm-list').innerHTML = sorted().map(card).join('');
      } catch(e) {} finally { loading = false; }
    }
    const STAT = { progress:'In progress', planned:'Planned', idea:'Suggested', shipped:'Shipped' };
    function sorted(){
      const list = items().filter(it => sort !== 'progress' || it.s === 'progress');
      if (sort === 'new') return remote ? list.slice().sort((a, b) => String(b.at).localeCompare(String(a.at))) : list.slice().reverse();
      return list.slice().sort((a, b) => count(b) - count(a) || (a.s === 'progress' ? -1 : 0));
    }
    const card = it => `<div class="rm-c ${votes[it.id] ? 'voted' : ''}" data-id="${it.id}"><button class="rm-vote" aria-pressed="${!!votes[it.id]}" aria-label="Upvote ${esc(it.t)}">${ic('arrow_upward','sm')}<span class="rm-n"><span>${count(it)}</span></span></button><div class="rm-tx"><div class="rm-t">${esc(it.t)}</div><div class="rm-d">${esc(it.d)}</div><div class="rm-meta"><span class="rm-st ${it.s}">${STAT[it.s] || it.s}</span><span class="rm-tag">${esc(it.tag)}</span></div></div></div>`;
    function roadmap(){
      inEl.innerHTML = `<div class="pv-h"><span class="dv-sec">Roadmap</span><h1>What we build next</h1><p>Upvote the components you want most, or suggest a new one. The most wanted ideas move up the list.</p></div>
        <div class="rm-add"><input id="rm-in" placeholder="Suggest a component, for example a pricing calculator" autocomplete="off" maxlength="120" value="${esc(prefill)}"><button class="su-btn" id="rm-go">Suggest</button></div>
        <div class="rm-bar"><div class="dv-tabs" role="tablist">${[['top','Most wanted'],['new','Newest'],['progress','In progress']].map(t => `<button class="dv-tab" role="tab" data-s="${t[0]}" aria-selected="${t[0] === sort}">${t[1]}</button>`).join('')}</div><span class="rm-note">${LIVE ? 'One vote per idea, change it any time' : 'Votes are saved in this browser'}</span></div>
        <div class="rm-list" id="rm-list">${sorted().map(card).join('')}</div>`;
      prefill = '';
      if ($('#rm-in').value) setTimeout(() => $('#rm-in').focus(), 300);
      load();
    }
    function relist(){
      const list = $('#rm-list'), before = new Map($$('.rm-c', list).map(el => [el.dataset.id, el.getBoundingClientRect().top]));
      const els = new Map($$('.rm-c', list).map(el => [el.dataset.id, el]));
      sorted().forEach(it => { const el = els.get(it.id); if (el) list.appendChild(el); });
      $$('.rm-c', list).forEach(el => { const dy = before.get(el.dataset.id) - el.getBoundingClientRect().top; if (dy && !reduce) el.animate([{ transform:`translateY(${dy}px)` }, { transform:'none' }], { duration:520, easing:'cubic-bezier(.16,1,.3,1)' }); });
    }
    function paintVote(v, id, it){
      const c = v.closest('.rm-c'), n = v.querySelector('.rm-n'), old = n.firstElementChild;
      c.classList.toggle('voted', !!votes[id]); v.setAttribute('aria-pressed', !!votes[id]);
      const nu = document.createElement('span'); nu.textContent = count(it); nu.className = votes[id] ? 'in-up' : 'in-down'; old.className = votes[id] ? 'out-up' : 'out-down'; n.appendChild(nu); setTimeout(() => old.remove(), 360);
    }
    pv.addEventListener('click', e => {
      const v = e.target.closest('.rm-vote');
      if (v){
        const id = v.closest('.rm-c').dataset.id, it = items().find(x => x.id === id);
        votes[id] = !votes[id]; if (!votes[id]) delete votes[id]; save(); paintVote(v, id, it);
        if (votes[id]){ v.classList.remove('pop'); void v.offsetWidth; v.classList.add('pop'); const plus = document.createElement('span'); plus.className = 'rm-plus'; plus.textContent = '+1'; v.appendChild(plus); setTimeout(() => plus.remove(), 800); Sound.play('pop'); track('Vote', { idea:it.t }); }
        else Sound.play('tick');
        if (LIVE) rpc('toggle_vote', { p_idea:id, p_voter:voter }).then(total => { it.base = Number(total) - (votes[id] ? 1 : 0); }).catch(() => { votes[id] = !votes[id]; if (!votes[id]) delete votes[id]; paintVote(v, id, it); showToast('Your vote did not save, try again'); });
        if (sort === 'top') setTimeout(relist, 420);
        return;
      }
      const t = e.target.closest('.dv-tab[data-s]'); if (t){ sort = t.dataset.s; $$('.dv-tab[data-s]', pv).forEach(x => x.setAttribute('aria-selected', x === t)); const list = $('#rm-list'); list.innerHTML = sorted().map(card).join(''); $$('.rm-c', list).forEach((el, i) => el.animate([{ opacity:0, transform:'translateY(8px)' }, { opacity:1, transform:'none' }], { duration:380, delay:i * 30, easing:'cubic-bezier(.16,1,.3,1)', fill:'backwards' })); Sound.play('tab'); return; }
      if (e.target.closest('#rm-go')) suggest();
      const ln = e.target.closest('.chg-link'); if (ln){ const c = find(ln.dataset.n); if (c){ close(false); setTimeout(() => c.querySelector('.exp-btn').click(), 60); } }
    });
    pv.addEventListener('keydown', e => { if (e.key === 'Enter' && e.target.id === 'rm-in') suggest(); });
    async function suggest(){
      const inp = $('#rm-in'), v = inp.value.trim(); if (v.length < 3){ inp.focus(); Sound.play('fail'); return; }
      track('Suggest', { idea:v });
      if (LIVE){
        try { await rpc('suggest_idea', { p_title:v, p_voter:voter }); inp.value = ''; Sound.play('done'); showToast('Thanks, new ideas show up once we review them'); }
        catch(e){ showToast('Your idea did not send, try again'); }
        return;
      }
      const id = 'idea-' + Date.now(); extra.push({ id, t:v, d:'Suggested by you', s:'idea', tag:'Idea' }); votes[id] = true; save(); inp.value = '';
      sort = 'new'; roadmap(); Sound.play('done'); showToast('Thanks, your idea is on the roadmap');
      const first = $('#rm-list .rm-c'); if (first) first.animate([{ opacity:0, transform:'scale(.96)' }, { opacity:1, transform:'none' }], { duration:450, easing:'cubic-bezier(.34,1.56,.64,1)' });
    }
    // privacy notice
    function privacy(){
      inEl.innerHTML = `<div class="pv-h"><span class="dv-sec">Privacy</span><h1>Privacy notice</h1><p>Last updated November 2026. This notice explains what we collect on designme.dev, why, and what you can do about it.</p></div>
      <div class="pp">
        <h2>Who we are</h2><p>Designme.dev is run by DESIGNME SPÓŁKA Z OGRANICZONĄ ODPOWIEDZIALNOŚCIĄ, Aleja Grunwaldzka 409, 80-309 Gdańsk, Poland, registered under KRS 0001185622, NIP 5833543632 and REGON 542307693. We are the controller of the personal data described here, and you can reach us at <a href="mailto:hello@designme.agency">hello@designme.agency</a>.</p>
        <h2>What we collect</h2>
        <p><b>Your email address</b>, when you sign up for updates. We use it to send new components and library news, and nothing else.</p>
        <p><b>Roadmap ideas and votes.</b> Your browser creates a random ID so you can vote once per idea, and we store that ID with your votes and any idea you suggest. It does not include your name or email.</p>
        <p><b>A scrambled form of your IP address.</b> To stop one person flooding sign-ups, votes or ideas, we keep a one-way hash of your IP address, never the address itself, when you sign up, vote or suggest an idea, and use it to limit how often that can happen.</p>
        <p><b>Usage statistics.</b> We count page views and actions such as copying code with Plausible Analytics, which does not use cookies and does not collect personal data.</p>
        <p><b>Settings in your browser.</b> Your theme, style and accent colour are kept in your browser's local storage, and whether sound is on is kept in its session storage until you close the tab. None of it is sent to us.</p>
        <h2>Why we use it</h2><p>We send updates because you asked for them, so the legal basis is your consent (Art. 6(1)(a) GDPR), and you can withdraw it at any time with the unsubscribe link in every email. We run the roadmap and usage statistics to decide what to build next, and keep the hashed IP address to prevent abuse, which are our legitimate interests (Art. 6(1)(f) GDPR).</p>
        <h2>Who helps us</h2><p>Supabase stores sign-ups and roadmap votes, Plausible provides usage statistics and Cloudflare hosts the site. If we start sending emails through an email service, we will name it here before your address goes to it. The star count in the header comes from GitHub: your browser asks GitHub's public API for it once per visit, so GitHub sees that request and your IP address, as with any site you open. The fonts are served from designme.dev itself, so loading the site sends nothing to Google. Some of them process data outside the European Economic Area, and where that happens it is covered by safeguards such as the European Commission's Standard Contractual Clauses.</p>
        <h2>Children</h2><p>Designme.dev is made for people building products and is not aimed at children, so we do not knowingly collect emails from anyone under 16. If you think a child has signed up, email us and we will delete it.</p>
        <h2>How long we keep it</h2><p>We keep your email until you unsubscribe or ask us to delete it, and roadmap votes, with the hashed IP address stored alongside them, for as long as the roadmap runs. The record used to limit sign-ups, votes and ideas deletes itself after two days. Usage statistics are aggregated and contain no personal data.</p>
        <h2>Your rights</h2><p>You can ask to access, correct, delete or export your data, object to processing based on legitimate interest, or restrict how we use it. Email us at <a href="mailto:hello@designme.agency">hello@designme.agency</a> and we will reply within 30 days. You can also complain to the Polish data protection authority, the President of the Personal Data Protection Office (UODO), ul. Stawki 2, 00-193 Warsaw.</p>
      </div>`;
    }
