      menu.addEventListener('click', e => { const b = e.target.closest('[data-r]'); if (!b) return; const r = RANGES.find(x => x[0] === b.dataset.r);
        $$('[data-r]', menu).forEach(x => x.setAttribute('aria-checked', x === b)); rangeBtn.querySelector('span').textContent = r[0]; menu.classList.remove('open'); rangeBtn.setAttribute('aria-expanded', false); Sound.play('select');
        [r[1], r[2]].forEach(label => $$('.lb .seg button', grid).forEach(sb => { if (sb.textContent.trim() === label && !sb.classList.contains('on')) sb.click(); })); });
      board.addEventListener('click', e => { if (!e.target.closest('.la-range-w')) { menu.classList.remove('open'); rangeBtn.setAttribute('aria-expanded', false); } });
      // search filters what it can: kanban cards, account rows and pages
      $('.la-search input', board).addEventListener('input', e => { const q = e.target.value.trim().toLowerCase();
        $$('.kb-card, #c12 .gt-row:not(.gt-head), .tpg-r', grid).forEach(r => { r.style.display = !q || r.textContent.toLowerCase().includes(q) ? '' : 'none'; }); });
      // account rows open the details drawer
      const la = $('.la', board);
