    wrap.innerHTML = `<button class="acc-btn" id="acc-btn" aria-haspopup="dialog" aria-expanded="false" aria-label="Accent colour"><i class="acc-dot"></i></button>
      <div class="acc-pop" id="acc-pop" role="dialog" aria-label="Accent colour">
        <div class="acc-h"><span class="acc-t">Accent colour</span><button class="acc-shuffle">${ic('shuffle','sm')}Surprise me</button></div>
        <div class="acc-row" role="radiogroup" aria-label="Accent colour">${swatches()}</div>
        <div class="acc-f"><span class="acc-hex"></span><button class="acc-reset">Reset</button></div>
      </div>`;
    // it lives in the header next to the style switch, wherever the switch itself currently sits
    { const ta = $('.top .top-actions'), seg = $('#style-seg'); if (seg.parentElement === ta) seg.after(wrap); else { const mark = [...ta.childNodes].find(n => n.nodeType === 8); mark ? mark.after(wrap) : ta.prepend(wrap); } }
    // mobile: the same swatches as a row in the menu
    const styleRow = $('#m-seg-slot') && $('#m-seg-slot').closest('.m-set');
    if (styleRow){ const row = document.createElement('div'); row.className = 'm-set mi-in'; row.innerHTML = `<span class="m-lbl">Accent</span><span class="m-acc acc-row" role="radiogroup" aria-label="Accent colour">${swatches()}</span>`; styleRow.after(row); }
    const pop = $('#acc-pop'), btn = $('#acc-btn');
    // the swatch the style hides, as its Default is the same colour
    const twin = b => b.dataset.v === (document.documentElement.getAttribute('data-style') === 'soft' ? '#116ff8' : '#d4f84a');
    document.addEventListener('keydown', e => {
      const b = e.target.closest && e.target.closest('.acc-row .acc-sw[data-v]'); if (!b) return;
      const sws = $$('.acc-sw[data-v]', b.parentElement).filter(x => !twin(x)), i = sws.indexOf(b);
      const d = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 0;
      const n = d ? sws[(i + d + sws.length) % sws.length] : e.key === 'Home' ? sws[0] : e.key === 'End' ? sws[sws.length - 1] : null;
      if (!n) return; e.preventDefault(); commit(n.dataset.v, n); n.focus();
    });
    const label = v => v === 'default' ? (document.documentElement.getAttribute('data-style') === 'soft' ? 'Blue, the Soft default' : 'Lime, the Blueprint default') : v.toUpperCase();
    function mark(){
      $$('.acc-sw[data-v]').forEach(b => { const on = b.dataset.v === cur; b.classList.toggle('on', on); b.setAttribute('aria-checked', String(on)); });
      $$('.acc-row').forEach(row => { const all = $$('.acc-sw[data-v]', row), sws = all.filter(b => !twin(b)), on = sws.find(b => b.dataset.v === cur) || sws[0]; all.forEach(b => { b.tabIndex = b === on ? 0 : -1; }); });
      const known = SW.some(s => s[0] === cur); $$('.acc-custom').forEach(l => { l.classList.toggle('on', !known); if (!known) l.style.setProperty('--sw', cur); else l.style.removeProperty('--sw'); });
      $('.acc-hex').textContent = label(cur);
    }
    function commit(v, el){
      cur = v; try { localStorage.setItem('dmui-accent', v); } catch(e) {}
      apply(v); mark(); Sound.play('select'); track('Accent', { color:v });
      if (el && !reduce) el.animate([{ transform:'scale(1)' }, { transform:'scale(1.25)' }, { transform:'scale(1)' }], { duration:380, easing:'cubic-bezier(.34,1.56,.64,1)' });
    }
    // hovering a swatch previews it, leaving puts the chosen one back
    document.addEventListener('pointerover', e => { const b = e.target.closest('.acc-pop .acc-sw[data-v]'); if (b && matchMedia('(hover: hover)').matches) apply(b.dataset.v); });
    pop.addEventListener('pointerleave', () => apply(cur));
    document.addEventListener('click', e => {
      const b = e.target.closest('.acc-sw[data-v]'); if (b){ commit(b.dataset.v, b); return; }
      if (e.target.closest('.acc-shuffle')){ const h = Math.floor(Math.random() * 360), s = 70 + Math.random() * 20, l = 48 + Math.random() * 8; const v = hslHex(h, s, l); commit(v, $('.acc-custom')); return; }
      if (e.target.closest('.acc-reset')){ commit('default', $('.acc-sw[data-v="default"]')); return; }
    });
