  /* ---------- custom select ---------- */
  function enhanceSelect(sel){
    if (!sel || sel._cs) return; sel._cs = true; sel.classList.add('ns-hide');
    const btn = document.createElement('button'); btn.type = 'button'; btn.className = 'csel';
    btn.setAttribute('aria-haspopup', 'listbox'); btn.setAttribute('aria-expanded', 'false');
    const lab = () => { const o = sel.options[sel.selectedIndex]; btn.textContent = o ? o.textContent : ''; };
    sel.after(btn); lab();
    const pop = document.createElement('div'); pop.className = 'csel-pop'; pop.setAttribute('role', 'listbox'); document.body.appendChild(pop);
    let idx = 0;
    const paint = () => $$('.csel-i', pop).forEach((b, i) => b.classList.toggle('act', i === idx));
    function open(){
      pop.innerHTML = [...sel.options].map((o, i) => `<button type="button" class="csel-i ${i === sel.selectedIndex ? 'sel' : ''}" role="option" data-i="${i}">${o.textContent}${ic('check','sm')}</button>`).join('');
      idx = sel.selectedIndex; paint();
      const host = btn.closest('.fz-in,.fld') || btn, r = host.getBoundingClientRect();
      pop.style.minWidth = r.width + 'px'; pop.style.left = r.left + 'px'; pop.style.top = (r.bottom + 6) + 'px';
      pop.classList.add('show'); btn.setAttribute('aria-expanded', 'true'); Sound.play('open');
    }
    function close(){ if (!pop.classList.contains('show')) return; pop.classList.remove('show'); btn.setAttribute('aria-expanded', 'false'); }
    function choose(i){ sel.selectedIndex = i; lab(); sel.dispatchEvent(new Event('change', { bubbles:true })); close(); Sound.play('select'); btn.focus(); }
    btn.addEventListener('click', e => { e.preventDefault(); pop.classList.contains('show') ? close() : open(); });
    btn.addEventListener('keydown', e => {
      const n = sel.options.length, isOpen = pop.classList.contains('show');
      if (!isOpen && ['ArrowDown','Enter',' '].includes(e.key)){ e.preventDefault(); open(); return; }
      if (!isOpen) return;
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); idx = (idx + (e.key === 'ArrowDown' ? 1 : -1) + n) % n; paint(); Sound.play('tick'); }
      else if (e.key === 'Enter'){ e.preventDefault(); choose(idx); }
      else if (e.key === 'Escape' || e.key === 'Tab') close();
    });
    pop.addEventListener('mousedown', e => { const b = e.target.closest('.csel-i'); if (b){ e.preventDefault(); choose(+b.dataset.i); } });
    document.addEventListener('pointerdown', e => { if (!pop.contains(e.target) && !btn.contains(e.target)) close(); });
    addEventListener('scroll', close, { passive:true });
    sel.addEventListener('change', lab);
  }
   
