  /* ---------- equal card heads: cards side by side start their previews on the same line ---------- */
  {
    const textH = p => { const r = document.createRange(); r.selectNodeContents(p); return r.getBoundingClientRect().height; };
    function eq(){
      $$('.lib-sec .grid').forEach(g => {
        const rows = {};
        $$(':scope>.comp:not(.wide)', g).forEach(c => { if (c.offsetParent === null) return; (rows[c.offsetTop] = rows[c.offsetTop] || []).push($('.comp-desc', c)); });
        Object.values(rows).forEach(r => {
          if (r.length < 2){ r.forEach(p => { if (p.style.minHeight) p.style.minHeight = ''; }); return; }
          const tall = r.reduce((a, p) => textH(p) > textH(a) ? p : a);
          tall.style.minHeight = '';
          const h = tall.getBoundingClientRect().height + 'px';
          r.forEach(p => { if (p !== tall && p.style.minHeight !== h) p.style.minHeight = h; });
        });
      });
    }
    let t = 0; const q = () => { clearTimeout(t); t = setTimeout(eq, 60); };
    addEventListener('resize', q);
    if (document.fonts) document.fonts.ready.then(q);
    if ('ResizeObserver' in window){ const ro = new ResizeObserver(q); $$('.lib-sec .grid').forEach(g => ro.observe(g)); }
    eq();
  }

